-- ============================================================================
-- Hoppaz: the "Lagos HQ" room template (lagos-hq), layout rows for both widths.
-- GENERATED by scripts/crew-room/export-layouts.mjs --only lagos-hq --out supabase/lagos_hq_template.sql
-- from src/lib/campaign/templates.ts. Do not edit by hand: change the room, run the script, load the file.
--
-- Run order: after crew_rooms.sql AND crew_rooms_scale.sql.
-- Safe to run twice (and as often as you like): it only inserts or refreshes the lagos-hq rows. It touches no other
-- template, no room, no walker and no function.
-- Re-run rule: crew_rooms.sql puts the old slow helpers back and says so; run crew_rooms_scale.sql after it. Your lagos-hq
-- rows survive both, but running this file again after them is harmless and re-checks the grids.
--
-- What it does: one transaction. It inserts the layout of lagos-hq at widths 30 and 36 (the walls and furniture as
-- blocks, the zones, the spawn). crew_rooms_scale.sql keeps a trigger on crew_room_layouts that fills the ready-made walk grid
-- (walk) and the area look-up (area_at) from that data on every insert and update, so no extra step is needed; the last
-- statement checks they were filled and that the spawn and every zone stop are walkable tiles. A crew picks the template in
-- MANAGE CREW (crew_room_set_template) once these rows exist.
-- ============================================================================
begin;
set local lock_timeout = '3s';

do $guard$
begin
  if to_regclass('public.crew_room_layouts') is null or to_regprocedure('public.crew_room_set_template(uuid,text)') is null then
    raise exception 'lagos-hq: crew_rooms.sql must be loaded first';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'crew_room_layouts' and column_name = 'walk')
     or not exists (select 1 from pg_trigger where tgrelid = 'public.crew_room_layouts'::regclass and tgname = 'crew_room_layout_grids' and not tgisinternal) then
    raise exception 'lagos-hq: crew_rooms_scale.sql must be loaded first (it keeps the walk grid of each layout)';
  end if;
end $guard$;

insert into public.crew_room_layouts(template,width,data) values
('lagos-hq',30,'{"grid":{"width":30,"height":20,"tile":32},"spawn":{"x":15,"y":17},"zones":[{"id":"lagoon","name":"LAGOON SIDE","subtitle":"Water, wind, a jetty","material":"paving","x":1,"y":1,"w":9,"h":8,"stop":{"x":4,"y":6},"plaque":{"x":5,"y":7},"number":"01"},{"id":"stage","name":"THE STAGE","subtitle":"Music on the street","material":"paving","x":10,"y":1,"w":10,"h":8,"stop":{"x":13,"y":7},"plaque":{"x":13,"y":6},"number":"02"},{"id":"market","name":"MARKET","subtitle":"Akara, phones, cloth","material":"paving","x":20,"y":1,"w":9,"h":8,"stop":{"x":24,"y":4},"plaque":{"x":24,"y":5},"number":"03"},{"id":"busstop","name":"BUS STOP","subtitle":"Danfos and okadas","material":"paving","x":1,"y":9,"w":10,"h":10,"stop":{"x":4,"y":16},"plaque":{"x":4,"y":18},"number":"04"},{"id":"junction","name":"THE JUNCTION","subtitle":"The way to the map","material":"paving","x":11,"y":9,"w":8,"h":10,"stop":{"x":15,"y":14},"plaque":{"x":16,"y":14},"number":"05"},{"id":"suya","name":"SUYA SPOT","subtitle":"Smoke and stools","material":"paving","x":19,"y":9,"w":10,"h":10,"stop":{"x":23,"y":16},"plaque":{"x":23,"y":18},"number":"06"}],"privateAreas":[],"blocks":[{"id":"lagoon-l","kind":"lagoon","x":1,"y":1,"w":3,"h":3,"solid":true},{"id":"lagoon-r","kind":"lagoon","x":6,"y":1,"w":3,"h":3,"solid":true,"variant":1},{"id":"palm-1","kind":"palm","x":9,"y":2,"w":1,"h":1,"solid":true},{"id":"palm-2","kind":"palm","x":1,"y":5,"w":1,"h":1,"solid":true},{"id":"hq-billboard","kind":"billboard","x":10,"y":1,"w":10,"h":3,"solid":true},{"id":"dj-booth","kind":"djdesk","x":13,"y":5,"w":4,"h":1,"solid":true},{"id":"stage-speaker-l","kind":"speakerstack","x":11,"y":4,"w":1,"h":2,"solid":true},{"id":"stage-speaker-r","kind":"speakerstack","x":18,"y":4,"w":1,"h":2,"solid":true},{"id":"stall-akara","kind":"stall","x":21,"y":1,"w":3,"h":2,"solid":true,"variant":0},{"id":"stall-phones","kind":"stall","x":25,"y":1,"w":3,"h":2,"solid":true,"variant":1},{"id":"stall-cloth","kind":"stall","x":21,"y":5,"w":3,"h":2,"solid":true,"variant":2},{"id":"umbrella-1","kind":"parasol","x":25,"y":5,"w":1,"h":1,"solid":true},{"id":"umbrella-2","kind":"parasol","x":27,"y":4,"w":1,"h":1,"solid":true},{"id":"danfo-1","kind":"danfo","x":2,"y":10,"w":3,"h":1,"solid":true,"variant":0},{"id":"danfo-2","kind":"danfo","x":12,"y":11,"w":3,"h":1,"solid":true,"variant":1},{"id":"keke-1","kind":"keke","x":17,"y":10,"w":2,"h":1,"solid":true,"variant":0},{"id":"hop-bus","kind":"hopbus","x":22,"y":10,"w":3,"h":1,"solid":true},{"id":"okada-1","kind":"okada","x":6,"y":12,"w":2,"h":1,"solid":true,"variant":0},{"id":"okada-2","kind":"okada","x":19,"y":12,"w":2,"h":1,"solid":true,"variant":1},{"id":"okada-3","kind":"okada","x":26,"y":11,"w":2,"h":1,"solid":true,"variant":0},{"id":"lamp-1","kind":"streetlamp","x":10,"y":8,"w":1,"h":1,"solid":true},{"id":"lamp-2","kind":"streetlamp","x":20,"y":8,"w":1,"h":1,"solid":true},{"id":"bus-shelter","kind":"busshelter","x":2,"y":14,"w":5,"h":2,"solid":true},{"id":"bus-stop-sign","kind":"busstop","x":8,"y":14,"w":1,"h":1,"solid":true},{"id":"suya-stall","kind":"suyastall","x":21,"y":14,"w":4,"h":2,"solid":true},{"id":"stool-1","kind":"stool","x":26,"y":15,"w":1,"h":1,"solid":true},{"id":"stool-2","kind":"stool","x":26,"y":17,"w":1,"h":1,"solid":true},{"id":"entry-map-table","kind":"mapboard","x":13,"y":16,"w":2,"h":1,"solid":true}]}'::jsonb),
('lagos-hq',36,'{"grid":{"width":36,"height":20,"tile":32},"spawn":{"x":18,"y":17},"zones":[{"id":"lagoon","name":"LAGOON SIDE","subtitle":"Water, wind, a jetty","material":"paving","x":1,"y":1,"w":9,"h":8,"stop":{"x":4,"y":6},"plaque":{"x":5,"y":7},"number":"01"},{"id":"stage","name":"THE STAGE","subtitle":"Music on the street","material":"paving","x":13,"y":1,"w":10,"h":8,"stop":{"x":16,"y":7},"plaque":{"x":16,"y":6},"number":"02"},{"id":"market","name":"MARKET","subtitle":"Akara, phones, cloth","material":"paving","x":26,"y":1,"w":9,"h":8,"stop":{"x":30,"y":4},"plaque":{"x":30,"y":5},"number":"03"},{"id":"busstop","name":"BUS STOP","subtitle":"Danfos and okadas","material":"paving","x":1,"y":9,"w":13,"h":10,"stop":{"x":4,"y":16},"plaque":{"x":4,"y":18},"number":"04"},{"id":"junction","name":"THE JUNCTION","subtitle":"The way to the map","material":"paving","x":14,"y":9,"w":8,"h":10,"stop":{"x":18,"y":14},"plaque":{"x":19,"y":14},"number":"05"},{"id":"suya","name":"SUYA SPOT","subtitle":"Smoke and stools","material":"paving","x":22,"y":9,"w":13,"h":10,"stop":{"x":29,"y":16},"plaque":{"x":29,"y":18},"number":"06"}],"privateAreas":[],"blocks":[{"id":"lagoon-l","kind":"lagoon","x":1,"y":1,"w":3,"h":3,"solid":true},{"id":"lagoon-r","kind":"lagoon","x":6,"y":1,"w":3,"h":3,"solid":true,"variant":1},{"id":"palm-1","kind":"palm","x":9,"y":2,"w":1,"h":1,"solid":true},{"id":"palm-2","kind":"palm","x":1,"y":5,"w":1,"h":1,"solid":true},{"id":"hq-billboard","kind":"billboard","x":13,"y":1,"w":10,"h":3,"solid":true},{"id":"dj-booth","kind":"djdesk","x":16,"y":5,"w":4,"h":1,"solid":true},{"id":"stage-speaker-l","kind":"speakerstack","x":14,"y":4,"w":1,"h":2,"solid":true},{"id":"stage-speaker-r","kind":"speakerstack","x":21,"y":4,"w":1,"h":2,"solid":true},{"id":"stall-akara","kind":"stall","x":27,"y":1,"w":3,"h":2,"solid":true,"variant":0},{"id":"stall-phones","kind":"stall","x":31,"y":1,"w":3,"h":2,"solid":true,"variant":1},{"id":"stall-cloth","kind":"stall","x":27,"y":5,"w":3,"