on conflict(template,width) do update set data=excluded.data;

-- The grids are kept by the trigger; refuse to commit if they are not there or the room cannot be walked.
do $verify$
declare
  l record;
  z jsonb;
  tiles int;
begin
  for l in select * from public.crew_room_layouts where template = 'lagos-hq' loop
    if l.gw is null or l.gh is null or l.walk is null or l.area_at is null
       or char_length(l.walk) <> l.gw * l.gh or coalesce(array_length(l.area_at, 1), 0) <> l.gw * l.gh then
      raise exception 'lagos-hq at width %: the walk grid is missing or the wrong size', l.width;
    end if;
    if substr(l.walk, (l.data->'spawn'->>'y')::int * l.gw + (l.data->'spawn'->>'x')::int + 1, 1) <> '1' then
      raise exception 'lagos-hq at width %: the spawn is not a walkable tile', l.width;
    end if;
    for z in select * from jsonb_array_elements(l.data->'zones') loop
      if substr(l.walk, (z->'stop'->>'y')::int * l.gw + (z->'stop'->>'x')::int + 1, 1) <> '1' then
        raise exception 'lagos-hq at width %: the stop of zone % is not a walkable tile', l.width, z->>'id';
      end if;
    end loop;
    tiles := char_length(replace(l.walk, '0', ''));
    if tiles < 120 then raise exception 'lagos-hq at width %: only % walkable tiles', l.width, tiles; end if;
    raise notice 'lagos-hq at width %: % x % tiles, % walkable', l.width, l.gw, l.gh, tiles;
  end loop;
  if (select count(*) from public.crew_room_layouts where template = 'lagos-hq') <> 2 then
    raise exception 'lagos-hq: expected 2 layout rows';
  end if;
end $verify$;

commit;
